// src/hooks/useTelegramWebApp.ts
import { useEffect, useRef, useState } from 'react';
import type { TelegramWebApp } from '../types/telegram-web-app';

export function useTelegramWebApp(): TelegramWebApp | null {
  const [webApp, setWebApp] = useState<TelegramWebApp | null>(null);

  useEffect(() => {
    const app = window.Telegram?.WebApp ?? null;
    if (!app) return;

    app.expand();
    if (app.isVersionAtLeast('6.1')) {
      app.setHeaderColor('secondary_bg_color');
      app.setBackgroundColor('secondary_bg_color');
    }
    setWebApp(app);
  }, []);

  return webApp;
}

export function useTelegramBackButton(onBack: () => void): void {
  const webApp = useTelegramWebApp();
  const onBackRef = useRef(onBack);
  onBackRef.current = onBack;

  useEffect(() => {
    const backButton = webApp?.BackButton;
    if (!backButton) return;

    const handler = () => onBackRef.current();
    backButton.onClick(handler);
    backButton.show();

    return () => {
      backButton.offClick(handler);
      backButton.hide();
    };
  }, [webApp]);
}

interface MainButtonOptions {
  text: string;
  onClick: () => void;
  disabled?: boolean;
  progress?: boolean;
}

export function useTelegramMainButton({ text, onClick, disabled = false, progress = false }: MainButtonOptions): void {
  const webApp = useTelegramWebApp();
  const onClickRef = useRef(onClick);
  onClickRef.current = onClick;

  useEffect(() => {
    const mainButton = webApp?.MainButton;
    if (!mainButton) return;

    const handler = () => onClickRef.current();
    mainButton.onClick(handler);
    mainButton.show();

    return () => {
      mainButton.offClick(handler);
      mainButton.hide();
    };
  }, [webApp]);

  useEffect(() => {
    const mainButton = webApp?.MainButton;
    if (!mainButton) return;

    mainButton.setText(text);
    if (disabled) mainButton.disable();
    else mainButton.enable();
    if (progress) mainButton.showProgress(true);
    else mainButton.hideProgress();
  }, [webApp, text, disabled, progress]);
}

export function useTelegramFormGuards(isDirty: boolean): void {
  const webApp = useTelegramWebApp();

  useEffect(() => {
    if (!webApp) return;
    const supportsSwipeToggle = webApp.isVersionAtLeast('7.7');
    if (supportsSwipeToggle) webApp.disableVerticalSwipes();

    return () => {
      if (supportsSwipeToggle) webApp.enableVerticalSwipes();
      webApp.disableClosingConfirmation();
    };
  }, [webApp]);

  useEffect(() => {
    if (!webApp) return;
    if (isDirty) webApp.enableClosingConfirmation();
    else webApp.disableClosingConfirmation();
  }, [webApp, isDirty]);
}
