```tsx
// src/screens/CheckoutScreen.tsx
import { ChangeEvent, useCallback, useMemo, useState } from 'react';
import {
  useTelegramBackButton,
  useTelegramFormGuards,
  useTelegramMainButton,
  useTelegramWebApp,
} from '../hooks/useTelegramWebApp';
import { CartItem, DeliveryAddress, DeliveryAddressErrors, EMPTY_ADDRESS } from '../types/checkout';
import './CheckoutScreen.css';

export interface CheckoutScreenProps {
  items: CartItem[];
  currency?: string;
  deliveryFee?: number;
  onBack: () => void;
  onPay: (address: DeliveryAddress) => Promise<void> | void;
}

function formatCurrency(amount: number, currency: string): string {
  return new Intl.NumberFormat(undefined, { style: 'currency', currency }).format(amount);
}

function validateAddress(address: DeliveryAddress): DeliveryAddressErrors {
  const errors: DeliveryAddressErrors = {};
  if (!address.fullName.trim()) errors.fullName = 'Enter your full name';
  if (!/^[0-9+() -]{7,20}$/.test(address.phone.trim())) errors.phone = 'Enter a valid phone number';
  if (!address.city.trim()) errors.city = 'Enter a city';
  if (!address.street.trim()) errors.street = 'Enter a street address';
  if (!address.postalCode.trim()) errors.postalCode = 'Enter a postal code';
  return errors;
}

interface AddressFieldProps {
  id: keyof DeliveryAddress;
  label: string;
  value: string;
  error?: string;
  type?: string;
  autoComplete?: string;
  multiline?: boolean;
  required?: boolean;
  onChange: (field: keyof DeliveryAddress) => (e: ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => void;
  onBlur: (field: keyof DeliveryAddress) => () => void;
}

function AddressField({
  id,
  label,
  value,
  error,
  type = 'text',
  autoComplete,
  multiline = false,
  required = false,
  onChange,
  onBlur,
}: AddressFieldProps) {
  return (
    <div className="field">
      <label className="field__label" htmlFor={id}>
        {label}
        {required && (
          <span className="field__required" aria-hidden="true">
            {' '}*
          </span>
        )}
      </label>
      {multiline ? (
        <textarea
          id={id}
          className={`field__input field__input--textarea${error ? ' field__input--invalid' : ''}`}
          value={value}
          onChange={onChange(id)}
          onBlur={onBlur(id)}
          rows={3}
        />
      ) : (
        <input
          id={id}
          type={type}
          className={`field__input${error ? ' field__input--invalid' : ''}`}
          value={value}
          onChange={onChange(id)}
          onBlur={onBlur(id)}
          autoComplete={autoComplete}
          aria-invalid={Boolean(error)}
          aria-describedby={error ? `${id}-error` : undefined}
        />
      )}
      {error && (
        <p id={`${id}-error`} className="field__error">
          {error}
        </p>
      )}
    </div>
  );
}

export function CheckoutScreen({ items, currency = 'USD', deliveryFee = 0, onBack, onPay }: CheckoutScreenProps) {
  const webApp = useTelegramWebApp();
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});
  const [isDirty, setIsDirty] = useState(false);
  const [isPaying, setIsPaying] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);

  const subtotal = useMemo(() => items.reduce((sum, item) => sum + item.price * item.quantity, 0), [items]);
  const total = subtotal + deliveryFee;

  const liveErrors = useMemo(() => validateAddress(address), [address]);
  const isFormValid = Object.keys(liveErrors).length === 0;

  const handleChange = useCallback(
    (field: keyof DeliveryAddress) => (e: ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
      const { value } = e.target;
      setAddress((prev) => ({ ...prev, [field]: value }));
      setIsDirty(true);
    },
    []
  );

  const handleBlur = useCallback(
    (field: keyof DeliveryAddress) => () => {
      setTouched((prev) => ({ ...prev, [field]: true }));
    },
    []
  );

  const handlePay = useCallback(async () => {
    if (items.length === 0 || isPaying) return;

    if (!isFormValid) {
      setTouched({
        fullName: true,
        phone: true,
        country: true,
        city: true,
        street: true,
        apartment: true,
        postalCode: true,
        notes: true,
      });
      webApp?.HapticFeedback.notificationOccurred('error');
      return;
    }

    setSubmitError(null);
    setIsPaying(true);
    try {
      await onPay(address);
      webApp?.HapticFeedback.notificationOccurred('success');
      setIsDirty(false);
    } catch (err) {
      webApp?.HapticFeedback.notificationOccurred('error');
      setSubmitError(err instanceof Error ? err.message : 'Payment failed. Please try again.');
    } finally {
      setIsPaying(false);
    }
  }, [address, isFormValid, isPaying, items.length, onPay, webApp]);

  useTelegramBackButton(onBack);
  useTelegramMainButton({
    text: `Pay ${formatCurrency(total, currency)}`,
    onClick: handlePay,
    disabled: !isFormValid || items.length === 0 || isPaying,
    progress: isPaying,
  });
  useTelegramFormGuards(isDirty);

  return (
    <div className="checkout">
      <header className="checkout__header">
        <h1 className="checkout__title">Checkout</h1>
        {!webApp && (
          <button type="button" className="checkout__fallback-back" onClick={onBack}>
            ‹ Back to cart
          </button>
        )}
      </header>

      <section className="checkout__section" aria-labelledby="order-heading">
        <h2 id="order-heading" className="checkout__section-title">
          Your order
        </h2>

        {items.length === 0 ? (
          <p className="checkout__empty">Your cart is empty.</p>
        ) : (
          <>
            <ul className="cart-list">
              {items.map((item) => (
                <li key={item.id} className="cart-item">
                  {item.imageUrl && <img src={item.imageUrl} alt="" className="cart-item__thumb" />}
                  <div className="cart-item__info">
                    <span className="cart-item__name">{item.name}</span>
                    <span className="cart-item__meta">
                      Qty {item.quantity} · {formatCurrency(item.price, currency)}
                    </span>
                  </div>
                  <span className="cart-item__subtotal">{formatCurrency(item.price * item.quantity, currency)}</span>
                </li>
              ))}
            </ul>

            <div className="summary">
              <div className="summary__row">
                <span>Subtotal</span>
                <span>{formatCurrency(subtotal, currency)}</span>
              </div>
              <div className="summary__row">
                <span>Delivery</span>
                <span>{formatCurrency(deliveryFee, currency)}</span>
              </div>
              <div className="summary__row summary__row--total">
                <span>Total</span>
                <span>{formatCurrency(total, currency)}</span>
              </div>
            </div>
          </>
        )}
      </section>

      <section className="checkout__section" aria-labelledby="address-heading">
        <h2 id="address-heading" className="checkout__section-title">
          Delivery address
        </h2>
        <form className="address-form" onSubmit={(e) => e.preventDefault()} noValidate>
          <AddressField
            id="fullName"
            label="Full name"
            required
            value={address.fullName}
            error={touched.fullName ? liveErrors.fullName : undefined}
            onChange={handleChange}
            onBlur={handleBlur}
            autoComplete="name"
          />
          <AddressField
            id="phone"
            label="Phone number"
            required
            type="tel"
            value={address.phone}
            error={touched.phone ? liveErrors.phone : undefined}
            onChange={handleChange}
            onBlur={handleBlur}
            autoComplete="tel"
          />
          <div className="field-row">
            <AddressField
              id="country"
              label="Country"
              value={address.country}
              onChange={handleChange}
              onBlur={handleBlur}
              autoComplete="country-name"
            />
            <AddressField
              id="city"
              label="City"
              required
              value={address.city}
              error={touched.city ? liveErrors.city : undefined}
              onChange={handleChange}
              onBlur={handleBlur}
              autoComplete="address-level2"
            />
          </div>
          <AddressField
            id="street"
            label="Street address"
            required
            value={address.street}
            error={touched.street ? liveErrors.street : undefined}
            onChange={handleChange}
            onBlur={handleBlur}
            autoComplete="address-line1"
          />
          <div className="field-row">
            <AddressField
              id="apartment"
              label="Apartment / unit"
              value={address.apartment}
              onChange={handleChange}
              onBlur={handleBlur}
              autoComplete="address-line2"
            />
            <AddressField
              id="postalCode"
              label="Postal code"
              required
              value={address.postalCode}
              error={touched.postalCode ? liveErrors.postalCode : undefined}
              onChange={handleChange}
              onBlur={handleBlur}
              autoComplete="postal-code"
            />
          </div>
          <AddressField
            id="notes"
            label="Delivery notes (optional)"
            value={address.notes}
            onChange={handleChange}
            onBlur={handleBlur}
            multiline
          />
        </form>
      </section>

      {submitError && (
        <p className="checkout__error" role="alert">
          {submitError}
        </p>
      )}

      {!webApp && (
        <button
          type="button"
          className="checkout__fallback-pay"
          disabled={!isFormValid || items.length === 0 || isPaying}
          onClick={handlePay}
        >
          {isPaying ? 'Processing…' : `Pay ${formatCurrency(total, currency)}`}
        </button>
      )}
    </div>
  );
}
