export default function App() {
  const [screen, setScreen] = useState<'cart' | 'checkout'>('checkout');

  if (screen === 'cart') {
    return <div>Cart screen goes here.</div>;
  }

  const handlePay = async (address: DeliveryAddress) => {
    await new Promise((resolve) => setTimeout(resolve, 1200));
    console.log('Paying, deliver to:', address);
  };

  return (
    <CheckoutScreen
      items={SAMPLE_ITEMS}
      currency="USD"
      deliveryFee={4.99}
      onBack={() => setScreen('cart')}
      onPay={handlePay}
